HTML="""<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Nano AI</title><style>body{margin:0;background:#080b12;color:#edf2ff;font:15px system-ui}.app{display:grid;grid-template-columns:210px 1fr;min-height:100vh}.side{padding:18px;border-right:1px solid #202a3c;background:#0c111b}.brand{font-size:22px;font-weight:800;margin:8px 0 22px}button{cursor:pointer}nav button{display:block;width:100%;margin:5px 0;padding:11px;text-align:left;border:1px solid transparent;border-radius:10px;background:transparent;color:#aab6cf}nav button.active,nav button:hover{background:#151e2e;color:#fff}.main{padding:22px;max-width:1100px;width:100%;margin:auto}.page{display:none}.page.active{display:block}.panel{background:#111725;border:1px solid #26324a;border-radius:18px;padding:18px}.chat{height:58vh;overflow:auto}.msg{max-width:82%;padding:12px;margin:9px 0;border-radius:13px;white-space:pre-wrap}.user{margin-left:auto;background:#1b3155}.assistant{background:#161e2e}.composer{display:flex;gap:8px}.composer textarea{flex:1;background:#0b1019;color:#fff;border:1px solid #2a3850;border-radius:10px;padding:12px}.btn{padding:10px 14px;border-radius:10px;border:1px solid #33445f;background:#18243a;color:#fff}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px}.item{padding:12px;border:1px solid #27344a;border-radius:12px;background:#0d131e}@media(max-width:700px){.app{grid-template-columns:1fr}.side{border-right:0;border-bottom:1px solid #202a3c}}</style></head><body><div class='app'><aside class='side'><div class='brand'>◉ Nano AI</div><nav><button data-p='talk' class='active'>Talk</button><button data-p='memory'>Memory</button><button data-p='learning'>Learning</button><button data-p='skills'>Skills</button><button data-p='knowledge'>Knowledge</button><button data-p='model'>Model</button><button data-p='settings'>Settings</button><button data-p='system'>System</button></nav></aside><main class='main'><section id='talk' class='page active'><div class='panel'><h2>Talk <small id='status'></small></h2><div id='chat' class='chat'></div><div class='composer'><textarea id='input' placeholder='Talk to Nano...'></textarea><button class='btn' id='send'>Send</button></div></div></section><section id='memory' class='page'><div class='panel'><h2>Memory</h2><input id='mq' placeholder='Search memory' style='width:100%;padding:11px;background:#0b1019;color:white;border:1px solid #2a3850;border-radius:9px'><div id='ml' class='grid'></div></div></section><section id='learning' class='page'><div class='panel'><h2>Learning</h2><p>Explicit learning only. Model weights are never silently changed.</p><div id='ll' class='grid'></div></div></section><section id='skills' class='page'><div class='panel'><h2>Skills</h2><div id='sl' class='grid'></div></div></section><section id='knowledge' class='page'><div class='panel'><h2>Knowledge</h2><textarea id='kt' style='width:100%;height:180px;background:#0b1019;color:white;padding:11px'></textarea><p><button class='btn' onclick='ingest()'>Import locally</button></p><div id='kl' class='grid'></div></div></section><section id='model' class='page'><div class='panel'><h2>Model</h2><pre id='mi'></pre></div></section><section id='settings' class='page'><div class='panel'><h2>Settings</h2><div id='setl' class='grid'></div></div></section><section id='system' class='page'><div class='panel'><h2>System</h2><pre id='si'></pre></div></section></main></div><script>const $=x=>document.getElementById(x);const api=(u,o)=>fetch(u,o).then(async r=>{if(!r.ok)throw Error(await r.text());return r.json()});let cid=1;function add(r,t){let d=document.createElement('div');d.className='msg '+r;d.textContent=t;$('chat').appendChild(d);$('chat').scrollTop=$('chat').scrollHeight}async function send(){let t=$('input').value.trim();if(!t)return;$('input').value='';add('user',t);try{add('assistant',(await api('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({conversation_id:cid,message:t})})).answer)}catch(e){add('assistant','Error: '+e.message)}}$('send').onclick=send;$('input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send()}}function render(id,a){$(id).innerHTML=a.map(x=>'<div class=item><b>'+String(x.name||x.kind||'Memory')+'</b><p>'+String(x.content||x.description||x.payload||'')+'</p></div>').join('')}async function load(p){if(p==='memory')render('ml',await api('/api/memories'));if(p==='learning')render('ll',await api('/api/learning/events'));if(p==='skills')render('sl',await api('/api/skills'));if(p==='knowledge')render('kl',await api('/api/knowledge'));if(p==='model')$('mi').textContent=JSON.stringify(await api('/api/model'),null,2);if(p==='system')$('si').textContent=JSON.stringify(await api('/api/system'),null,2);if(p==='settings'){let s=await api('/api/settings');$('setl').innerHTML=Object.entries(s).map(([k,v])=>'<div class=item><b>'+k+'</b><br><input value="'+v+'" onchange="setv(\''+k+'\',this.value)"></div>').join('')}}async function setv(k,v){await api('/api/settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:k,value:v})})}async function ingest(){let t=$('kt').value;if(t)await api('/api/knowledge',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:t,source:'web-ui'})});$('kt').value='';load('knowledge')}document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));$(b.dataset.p).classList.add('active');document.querySelectorAll('nav button').forEach(x=>x.classList.remove('active'));b.classList.add('active');load(b.dataset.p)});api('/api/health').then(x=>$('status').textContent=x.model_reachable?' • online':' • offline').catch(()=>{});load('memory');</script></body></html>"""
